import{_ as n,o as i,c as s,a3 as t}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Linux und systemd","description":"ATLAS unter Linux installieren, aktualisieren und sichern.","frontmatter":{"title":"Linux und systemd","description":"ATLAS unter Linux installieren, aktualisieren und sichern."},"headers":[],"relativePath":"projects/atlas/linux.md","filePath":"projects/atlas/linux.md","lastUpdated":1792684236000}'),a={name:"projects/atlas/linux.md"};function r(l,e,d,h,u,p){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="linux-und-systemd" tabindex="-1">Linux und systemd <a class="header-anchor" href="#linux-und-systemd" aria-label="Permalink to &quot;Linux und systemd&quot;">​</a></h1><p>Der Linux-Installer ab ATLAS <strong>0.1.298</strong> verwendet denselben kombinierten App-Server wie Docker und die HA-App. Administration und Card Editor laufen zusammen; externe Plugins bleiben separat installierbar. Die optionale native <a href="/projects/atlas/frontend">ATLAS-Runtime-Integration</a> ist ebenfalls umgesetzt und über ein benutzerdefiniertes HACS-Repository auf Pi 5 und Proxmox geprüft.</p><h2 id="voraussetzungen" tabindex="-1">Voraussetzungen <a class="header-anchor" href="#voraussetzungen" aria-label="Permalink to &quot;Voraussetzungen&quot;">​</a></h2><ul><li>Linux mit laufendem systemd, Node.js ab Version 22 und Root-Zugriff für den Installer.</li><li>Ein auf Linux gebautes Paket für die CPU-Architektur, libc und Node-ABI des Zielsystems.</li><li>Drei freie Ports: 4176 für die App, 4175 und 4174 für interne Oberflächen.</li><li>Genügend Platz für mindestens zwei Laufzeitversionen und die Datensicherungen.</li></ul><p>AMD64 und ARM64 werden beim Paketbau unterstützt. Der Paketbau verwendet Debian Bookworm/glibc; ein Alpine/musl-Paket ist dafür nicht austauschbar. Zusätzlich ist der native Paketbau auf Raspberry Pi OS / Debian 13.7 Trixie mit glibc auf einem Raspberry Pi 4 (<code>aarch64</code>, 4 GB RAM) geprüft.</p><p>Prüfstand vom 15.10.2026: Debian 12 AMD64 im LXC sowie der native Pi 4 mit Node.js 22.23.3 und ATLAS 0.1.303/0.1.304. Auf dem Pi bestanden alle 17 Installer-Tests sowie Installation, Versionsupdate, Rollback, Backup, Dienstneustart und automatische Rückkehr nach einem fehlerhaften Update. Künstliche Plugin-/Projektdaten und Konfiguration blieben erhalten. Bei dieser ersten Prüfung blieben die Ports lokal gebunden. Anschließend wurden die LAN-Freigabe von Port 4176, ein echter Pi-4-Neustart, Autostart und ab 0.1.305 die dauerhafte Wiederherstellung der HA-Verbindung erfolgreich geprüft. Weitere Distributionen und Hardware benötigen eigene Qualifikation.</p><p>Der Installer verwendet den Systembenutzer <code>atlas</code>. Existiert dieser schon mit einem anderen Home-Verzeichnis oder einer anderen Hauptgruppe, bricht er ab. Er übernimmt keine fremde ATLAS-Installation automatisch.</p><h2 id="paket-vorbereiten" tabindex="-1">Paket vorbereiten <a class="header-anchor" href="#paket-vorbereiten" aria-label="Permalink to &quot;Paket vorbereiten&quot;">​</a></h2><p>Auf einem Linux-Buildsystem mit den vorhandenen Build-Abhängigkeiten:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux:prepare</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Das Ergebnis liegt unter <code>output/linux-runtime</code>. Das Verzeichnis enthält die gebaute Anwendung, Abhängigkeiten, das Referenzplugin und <code>atlas-linux-runtime.json</code>. Ein bestehendes Ausgabeverzeichnis wird nicht überschrieben.</p><p>Alternativ außerhalb des Ziel-LXC mit Docker bauen:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packaging/linux/Dockerfile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type=local,dest=output/linux-export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Der Export enthält ein Laufzeitarchiv, Manifest, Prüfsummen und die Node-Datei mit Lizenz aus dem offiziellen Node-Image. Prüfen Sie die Herkunft und SHA-256-Werte vor Verwendung. Verwenden Sie eine passende Node-Installation; ersetzen Sie eine vorhandene Node-Version nicht ungeprüft. Beim Transfer oder Entpacken bleiben die relativen Symlinks in <code>node_modules</code> erhalten.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Mit einem geprüften, entpackten Paket und einer passenden Node-Version:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/linux-runtime/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/linux-runtime</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> atlas</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4176/health</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Der Installer prüft Paket, Architektur und native Module, erstellt eine Sicherung, installiert eine eigene Laufzeitversion und startet den Dienst. Die Bereitschaftsprüfung verlangt beide Oberflächen, die erwartete App-Version und den Linux-Verteilungstyp. Belegte Ports anderer Dienste werden nicht durch Abschalten dieser Dienste freigemacht.</p><h2 id="dauerhafte-daten" tabindex="-1">Dauerhafte Daten <a class="header-anchor" href="#dauerhafte-daten" aria-label="Permalink to &quot;Dauerhafte Daten&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pfad</th><th>Inhalt</th></tr></thead><tbody><tr><td><code>/opt/atlas/releases/</code></td><td>Getrennte Laufzeitversionen.</td></tr><tr><td><code>/opt/atlas/current</code></td><td>Aktuelle Laufzeit als symbolischer Link.</td></tr><tr><td><code>/opt/atlas/installation.json</code></td><td>Installationsstand und vorherige Laufzeit.</td></tr><tr><td><code>/var/lib/atlas/</code></td><td>Dauerhafte Daten, Plugins, Identität, Dateihistorie und Papierkorb.</td></tr><tr><td><code>/etc/atlas/atlas.env</code></td><td>Geschützte Konfiguration; wird bei Updates erhalten.</td></tr><tr><td><code>/etc/systemd/system/atlas.service</code></td><td>Verwalteter Dienst.</td></tr><tr><td><code>/etc/systemd/system/atlas.service.d/</code></td><td>Eigene systemd-Ergänzungen.</td></tr><tr><td><code>/var/backups/atlas/</code></td><td>Zeitgestempelte Sicherungen.</td></tr></tbody></table><p>Editorprojekte und Teile der Administration liegen im Browser. Exportieren Sie diese zusätzlich in den jeweiligen Oberflächen. Eine Dateisicherung auf dem Server erfasst keinen Browser-Speicher. Behalten Sie bei Updates dieselbe Browseradresse, dieselbe Datenablage und dieselbe Installationsidentität bei, damit lokal gebundene verschlüsselte Zugangsdaten gültig bleiben. Docker-/HA-Daten werden nicht stillschweigend in eine neue Installation migriert.</p><h2 id="update-und-ruckwechsel" tabindex="-1">Update und Rückwechsel <a class="header-anchor" href="#update-und-ruckwechsel" aria-label="Permalink to &quot;Update und Rückwechsel&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/neues-paket/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /pfad/neues-paket</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/atlas/current/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollback</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Vor dem Update wird der ATLAS-Dienst gestoppt und dessen Datenstand gesichert. Umgebungsdatei, bestehende Plugins und systemd-Ergänzungen werden erhalten. Der Wechsel der Laufzeit erfolgt über den aktuellen Link. Scheitert die neue Laufzeit, wird die vorherige wiederhergestellt. Zuvor gestoppte Installationen bleiben nach der Prüfung gestoppt; die bisherige Boot-Aktivierung wird nicht geändert.</p><p>Der Rückwechsel betrifft den Programmstand. Er stellt nicht automatisch alte Benutzerdaten wieder her. Bei künftigen Datenmigrationen muss deren Rückwärts- kompatibilität separat geprüft werden. Alte Releases und Backups werden nicht automatisch gelöscht. Ändern Sie den verwalteten Dienst nicht direkt; <code>systemctl edit atlas</code> erstellt lokale Ergänzungen.</p><h2 id="sicherung-und-wiederherstellung" tabindex="-1">Sicherung und Wiederherstellung <a class="header-anchor" href="#sicherung-und-wiederherstellung" aria-label="Permalink to &quot;Sicherung und Wiederherstellung&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/atlas/current/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/atlas/current/scripts/atlas-linux-installer.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Die Sicherung erfolgt bei gestopptem Dienst und umfasst Daten, Konfiguration, Dienstdatei, Ergänzungen und Installationsmanifest. Danach startet ein zuvor aktiver Dienst wieder. Das Backup ist nur für Root zugänglich und kann Zugangsdaten enthalten. Externe Datenpfade, SSH-Schlüssel außerhalb der ATLAS-Datenablage und Browserprojekte müssen zusätzlich gesichert werden.</p><p>Für eine manuelle Wiederherstellung stoppen Sie ATLAS, sichern den aktuellen Stand erneut und stellen die ausgewählte Daten-/Konfigurationssicherung am ursprünglichen Ort mit passenden Besitzrechten wieder her. Bewahren Sie die Installationsidentität. Stellen Sie den dazu passenden Programmstand bereit und prüfen Sie danach <code>/health</code>. Eine Sicherung auf einer anderen Installation entsperrt keine dort gebundenen Secrets. Ein VM-/LXC-Snapshot vor der Erstinstallation bietet zusätzlich die Wiederherstellung des vollständigen Hosts.</p><h2 id="netzwerk-und-plugins" tabindex="-1">Netzwerk und Plugins <a class="header-anchor" href="#netzwerk-und-plugins" aria-label="Permalink to &quot;Netzwerk und Plugins&quot;">​</a></h2><p>Ab ATLAS 0.1.305 speichert die Linux-Administration beim Speichern der Einstellungen den gemerkten HA-Zugang zusätzlich serverseitig mit AES-GCM. Damit funktioniert die Wiederherstellung nach Dienst- und Host-Neustarts auch beim HTTP-LAN-Zugriff ohne Browser-Web-Crypto. Nach dem Update den vorhandenen Token einmal in der Administration eingeben und speichern; ältere Versionen haben ihn unter Umständen nur im Arbeitsspeicher gehalten.</p><p>Die verschlüsselte Datei <code>admin-connection.enc.json</code> und der private Schlüssel <code>admin-connection.enc.json.key</code> liegen neben <code>admin-device.json</code> im privaten ATLAS-Datenverzeichnis. Dateien haben unter Linux Modus <code>0600</code>; die Daten sind an die Installationsidentität gebunden. Ein vollständiges Datenbackup muss alle drei Dateien erhalten und vertraulich behandelt werden. Eine Kopie nur des Programmverzeichnisses oder des Browserexports enthält diesen Schlüssel nicht. „Token vergessen“ entfernt den gemerkten HA-Token auch aus dem serverseitigen Stand. Unlesbare verschlüsselte Daten werden nicht automatisch überschrieben.</p><p>Standardmäßig sind alle Oberflächen nur über Loopback erreichbar, Terminal ist deaktiviert. Der Installer öffnet keine Firewall. Für einen bewussten LAN-Betrieb kann der Administrator <code>ATLAS_APP_HOST</code> ändern und den Zugriff gezielt begrenzen; interne Ports bleiben lokal. Die Administration ist eine Verwaltungsoberfläche und gehört nicht ungeschützt ins Internet.</p><p>Bei File Studio müssen Linux-Dateirechte und die genehmigten Pfade zusammenpassen. Home-Assistant-Dateien auf einem anderen Host werden dadurch nicht automatisch eingebunden. SSH und Oh My Posh für das externe Terminal sind zusätzliche, optionale Voraussetzungen und nicht im Linux-Paket enthalten.</p><h2 id="testumfang" tabindex="-1">Testumfang <a class="header-anchor" href="#testumfang" aria-label="Permalink to &quot;Testumfang&quot;">​</a></h2><p>Installer-Regressionsprüfungen verwenden ausschließlich temporäre Testdaten. Sie prüfen Datenerhalt, Backup, fehlgeschlagenes Update, Rückwechsel, Dienstzustand, überschreibungsfreie Installation und Pfad-/ABI-Prüfungen. Ein erfolgreicher Container-Test mit simuliertem Dienst ersetzt keinen nativen systemd-Test. Native Ergebnisse und noch offene Plattformen stehen im <a href="/projects/atlas/entwicklungsstand">Entwicklungsstand</a>.</p>`,36)])])}const k=n(a,[["render",r]]);export{c as __pageData,k as default};
